// Presentation-only translations for the drawing studio and cutting planner.
// English source messages remain stable in geometry code and saved configurations.
// Each row is `en|ro|de|es|fr|it`. Translations are stored in that column order
// (without English), and FEATURE_LOCALE_COLUMNS maps a locale to its column.
export const FEATURE_LOCALES = Object.freeze(['en-US', 'ro-RO', 'de-DE', 'es-ES', 'fr-FR', 'it-IT']);
const FEATURE_LOCALE_COLUMNS = Object.freeze({ 'ro-RO': 0, 'de-DE': 1, 'es-ES': 2, 'fr-FR': 3, 'it-IT': 4 });
const FEATURE_LANGUAGE_LOCALES = Object.freeze({ en: 'en-US', ro: 'ro-RO', de: 'de-DE', es: 'es-ES', fr: 'fr-FR', it: 'it-IT' });
const messages = new Map();
function entries(rows) {
  for (const line of rows.trim().split('\n')) {
    const columns = line.split('|');
    if (columns.length !== FEATURE_LOCALES.length || columns.some((column) => !column.trim())) {
      throw new Error(`Incomplete roof translation (expected ${FEATURE_LOCALES.length} columns): ${columns[0]}`);
    }
    const [en, ...translations] = columns;
    messages.set(en, translations);
  }
}
